    en:{"guide.eyebrow":"User guide","guide.title":"How to use Zova","guide.subtitle":"From installation to your first saved class.","guide.learnEyebrow":"Learn with Zova","guide.learnTitle":"Live translation in 78 world languages.","guide.learnDescription":"Zova detects the lesson language automatically, then helps you follow the class with live transcription, translation, optional translated audio and study notes.","guide.free":"100% free to use","support.eyebrow":"We're here to help","support.title":"Zova Support"},
