  var guideDetailCopy = {
    en:{"guide.visualDescription":"Use this visual path to understand how Zova detects, translates and saves your lesson.","guide.installDescription":"Zova will be available from the Chrome Web Store soon. For now, you can install it as a developer or tester using the unpacked extension flow.","guide.apiDescription":"Before starting a lesson, connect Zova to Google Gemini with your own API key. Zova is 100% free to use; Google API limits or terms may apply separately.","guide.accessDescription":"When you start Zova on a classroom or video website, Chrome may ask you to allow access to that site.","guide.accessInstruction":"Click Allow only for the lesson page you selected. This lets Smart Class appear beside the classroom and work with the active session.","guide.smartDescription":"See original classroom content and the selected translation together as the lesson unfolds.","guide.helpDescription":"Use Explain, Answer or Summary when you need additional help understanding the lesson.","guide.helpInstruction":"These actions open Google AI Mode in a compact popup and submit bounded recent classroom context.","guide.dubbingDescription":"Dubbing (translated audio playback) is optional. You can enable or disable it separately from the rest of Zova.","guide.saveDescription":"Keep transcripts, translations and Smart Notes for later study — saved locally on your device.","guide.autosaveDescription":"While Smart Class is active, meaningful changes can be automatically saved — so you don't have to constantly press Save.","guide.reviewDescription":"Search, review, rename, export or delete saved lessons whenever you need them."},
    de:{"guide.visualDescription":"Nutze diesen visuellen Ablauf, um zu verstehen, wie Zova deine Lektion erkennt, übersetzt und speichert.","guide.installDescription":"Zova wird bald im Chrome Web Store verfügbar sein. Bis dahin kannst du die Erweiterung als Entwickler oder Tester entpackt installieren.","guide.apiDescription":"Verbinde Zova vor der ersten Lektion mit deinem eigenen Google-Gemini-API-Schlüssel. Zova ist kostenlos; Google-API-Limits oder Bedingungen können separat gelten.","guide.accessDescription":"Wenn du Zova auf einer Unterrichts- oder Videoseite startest, kann Chrome nach dem Zugriff auf diese Seite fragen.","guide.accessInstruction":"Klicke nur für die ausgewählte Lektion auf Erlauben. Dadurch kann Smart Class neben dem Unterricht erscheinen und mit der aktiven Sitzung arbeiten.","guide.smartDescription":"Sieh Original und ausgewählte Übersetzung gemeinsam, während die Lektion weiterläuft.","guide.helpDescription":"Nutze Erklären, Antwort oder Zusammenfassung, wenn du zusätzliche Hilfe beim Verstehen brauchst.","guide.helpInstruction":"Diese Aktionen öffnen Google AI Mode in einem kompakten Fenster und senden begrenzten aktuellen Unterrichtskontext.","guide.dubbingDescription":"Dubbing (übersetzte Audiowiedergabe) ist optional und kann unabhängig vom restlichen Zova aktiviert oder deaktiviert werden.","guide.saveDescription":"Bewahre Transkripte, Übersetzungen und Smart Notes lokal zum späteren Lernen auf.","guide.autosaveDescription":"Während Smart Class aktiv ist, können wichtige Änderungen automatisch gespeichert werden.","guide.reviewDescription":"Gespeicherte Lektionen suchen, prüfen, umbenennen, exportieren oder löschen."},
    zh:{"guide.visualDescription":"通过这条视觉路径了解 Zova 如何识别、翻译并保存课程。","guide.installDescription":"Zova 即将登陆 Chrome Web Store。目前可以通过解压扩展流程以开发者或测试者身份安装。","guide.apiDescription":"开始课程前，使用自己的 Google Gemini API 密钥连接 Zova。Zova 完全免费，Google API 可能有单独限制或条款。","guide.accessDescription":"在课堂或视频网站启动 Zova 时，Chrome 可能会请求网站访问权限。","guide.accessInstruction":"只为你选择的课程页面点击允许，这样 Smart Class 才能显示在课堂旁边并处理当前会话。","guide.smartDescription":"课程进行时，同时查看课堂原文和所选译文。","guide.helpDescription":"需要进一步理解课程时，使用解释、回答或总结。","guide.helpInstruction":"这些操作会在紧凑窗口中打开 Google AI Mode，并提交有限的近期课堂上下文。","guide.dubbingDescription":"配音（翻译音频播放）是可选功能，可以独立于其他 Zova 功能开启或关闭。","guide.saveDescription":"将转录、翻译和 Smart Notes 保存在本地，方便之后学习。","guide.autosaveDescription":"Smart Class 运行时，重要变化可以自动保存，无需不断点击保存。","guide.reviewDescription":"按需搜索、复习、重命名、导出或删除保存的课程。"},
    hi:{"guide.visualDescription":"इस दृश्य मार्ग से समझें कि Zova आपके पाठ को कैसे पहचानता, अनुवाद करता और सेव करता है।","guide.installDescription":"Zova जल्द ही Chrome Web Store पर उपलब्ध होगा। अभी इसे developer या tester के रूप में unpacked extension से इंस्टॉल कर सकते हैं।","guide.apiDescription":"पाठ शुरू करने से पहले अपनी Google Gemini API कुंजी से Zova कनेक्ट करें। Zova मुफ़्त है; Google API की सीमाएँ या शर्तें अलग हो सकती हैं।","guide.accessDescription":"कक्षा या वीडियो वेबसाइट पर Zova शुरू करते समय Chrome उस साइट की अनुमति माँग सकता है।","guide.accessInstruction":"केवल चुने गए पाठ पेज के लिए Allow पर क्लिक करें। इससे Smart Class कक्षा के पास दिखाई देगा और सक्रिय सत्र के साथ काम करेगा।","guide.smartDescription":"पाठ के दौरान मूल कक्षा सामग्री और चुना हुआ अनुवाद साथ-साथ देखें।","guide.helpDescription":"पाठ समझने में अतिरिक्त मदद के लिए Explain, Answer या Summary का उपयोग करें।","guide.helpInstruction":"ये क्रियाएँ छोटे पॉपअप में Google AI Mode खोलती हैं और सीमित हाल का कक्षा संदर्भ भेजती हैं।","guide.dubbingDescription":"Dubbing (अनुवादित ऑडियो) वैकल्पिक है और Zova की बाकी सुविधाओं से अलग चालू या बंद किया जा सकता है।","guide.saveDescription":"ट्रांसक्रिप्ट, अनुवाद और Smart Notes को बाद में पढ़ने के लिए स्थानीय रूप से रखें।","guide.autosaveDescription":"Smart Class सक्रिय होने पर महत्वपूर्ण बदलाव अपने आप सेव हो सकते हैं।","guide.reviewDescription":"जब चाहें सेव किए गए पाठ खोजें, देखें, नाम बदलें, निर्यात करें या हटाएँ।"}
  };
